ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
    "DeliveryLTEResponse": {
        "OrderId": payload.inputMessage.OrderFulfilment.Identification.ID,
        "ResponseCode": p('global.ack.responseCode') as Number,
        "ResponseDescription": p('global.ack.responseDescription')
    }
}

%dw 2.0
output application/json skipNullOn="everywhere"

var filterdItems =((payload.inputMessage.OrderFulfilment.SalesOrderLine filter upper($.ServiceActionCode) == p('global.add')) 
					filter ((item, index) -> 
					    p('global.addonPackage') contains ("|" ++ upper(item.ItemReference.PrimaryClassificationCode) ++ "|")
					))
var connectionNumber = (flatten(
                payload.inputMessage.OrderFulfilment.SalesOrderLine
                    map (o,i) -> 
                        if (upper(o.ItemReference.PrimaryClassificationCode) == upper(p('global.lteNumberClass')))  
                            (o.SpecificationGroupXA filter (upper($.Name) == upper(p('global.numero')))).Value
                        else null
            ) filter !isEmpty($))[0]
var isCtlAdd = !isEmpty((payload.inputMessage.OrderFulfilment.SalesOrderLine filter upper($.ServiceActionCode) == p('global.add'))
	filter $.ItemReference.PrimaryClassificationCode == p('global.lteControlPlanClass'))
var isCtlDel = !isEmpty((payload.inputMessage.OrderFulfilment.SalesOrderLine filter upper($.ServiceActionCode) == p('global.delete'))
	filter $.ItemReference.PrimaryClassificationCode == p('global.lteControlPlanClass'))
var isPosAdd = !isEmpty((payload.inputMessage.OrderFulfilment.SalesOrderLine filter upper($.ServiceActionCode) == p('global.add'))
	filter $.ItemReference.PrimaryClassificationCode == p('global.ltePostpaidPlanClass'))
var isPosDel = !isEmpty((payload.inputMessage.OrderFulfilment.SalesOrderLine filter upper($.ServiceActionCode) == p('global.delete'))
	filter $.ItemReference.PrimaryClassificationCode == p('global.ltePostpaidPlanClass'))
var isPreAdd = !isEmpty((payload.inputMessage.OrderFulfilment.SalesOrderLine filter upper($.ServiceActionCode) == p('global.add'))
	filter $.ItemReference.PrimaryClassificationCode == p('global.ltePrepaidPlanClass'))
var isPreDel = !isEmpty((payload.inputMessage.OrderFulfilment.SalesOrderLine filter upper($.ServiceActionCode) == p('global.delete'))
	filter $.ItemReference.PrimaryClassificationCode == p('global.ltePrepaidPlanClass'))
var processType =  if ( 
				        (isPosDel and isPosAdd) or (isCtlDel and isCtlAdd) or (isCtlDel and isPosAdd) or (isPosDel and isCtlAdd )
				    ) p('global.isPosPos')
					else if ( (isPosDel and isPreAdd) or (isCtlDel and isPreAdd) )
						p('global.isPosPre')
					else if ( (isPreDel and isPosAdd) or (isPreDel and isCtlAdd) )
						p('global.isPrePos')
					else if ( isPreDel and isPreAdd )
						p('global.isPrePre')
					else p('global.none')
---
{
  "planPackage": flatten((payload.inputMessage.OrderFulfilment.SalesOrderLine filter upper($.ServiceActionCode) == p('global.add')).SpecificationGroupXA) filter $.Name == p('global.serviceClassOcs') map {
      id: $.Value
  },
  "addonPackage": (flatten(filterdItems.SpecificationGroupXA) filter $.Name == p('global.offerClasseOcs')) map {
      id: $.Value
  },
  "billingAccountNumber": payload.inputMessage.BillingProcess.CustomerBill.BillingAccount.Number,
  "PAM": payload.inputMessage.BillingProcess.CustomerBill.InvoicingCycle,
  "integrationId": payload.inputMessage.OrderFulfilment.SalesOrderLine.Custom.AssetIntegrationID[0],
  "processType": processType,
  "msisdn": connectionNumber
}

%dw 2.0
var filterdItems = payload.inputMessage.OrderFulfilment.SalesOrderLine filter ((item, index) -> p("global.adicionRetiroSvaIds") contains ("|" ++ upper(item.ItemReference.PrimaryClassificationCode) ++ "|"))
var addonPackage = ((flatten((filterdItems map {
    "Items": $.SpecificationGroupXA 
    			map (o, i) -> o ++ { "ServiceActionCode": $.ServiceActionCode } }).Items)) 
    				filter $.Name == p('global.offerClasseOcs'))

var connectionNumber = (flatten(
                payload.inputMessage.OrderFulfilment.SalesOrderLine
                    map (o,i) -> 
                        if (upper(o.ItemReference.PrimaryClassificationCode) == upper(p('global.lteNumberClass')))  
                            (o.SpecificationGroupXA filter (upper($.Name) == upper(p('global.numero')))).Value
                        else null
            ) filter !isEmpty($))[0]
output application/json  
---
{
  "addonPackage": if (p('global.adicionRetiroFlagMap') == "true") 
  	// En caso de que el actionCode se obtenga de ServiceActionCode sin filtro de ADD en ServiceActionCode
    addonPackage map {
        id: $.Value,
        actionCode: $.ServiceActionCode
    }
    else 
    // En caso de que el actionCode se obtenga de SpecificationGroupXA.ActionCode con filtro de ADD en ServiceActionCode
    addonPackage filter $.ServiceActionCode == p('global.add') map {
        id: $.Value,
        actionCode: $.ActionCode
    },
  "integrationId": payload.inputMessage.OrderFulfilment.SalesOrderLine.Custom.AssetIntegrationID[0],
  "msisdn": connectionNumber
}

ee:variables.ee:set-variable:
output json
var connectionNumber = (flatten(
                payload.inputMessage.OrderFulfilment.SalesOrderLine
                    map (o,i) -> 
                        if (upper(o.ItemReference.PrimaryClassificationCode) == upper(p('global.lteNumberClass')))  
                            (o.SpecificationGroupXA filter (upper($.Name) == upper(p('global.numero')))).Value  
                            //o.Custom.AssetIntegrationID
                        else null
            ) filter !isEmpty($))[0]
---
if (!isEmpty(connectionNumber)) connectionNumber else null

