ee:message.ee:set-payload:
%dw 2.0
output application/json
var inputBody = payload.inputMessage
var connectionNumber = (flatten(
                payload.inputMessage.OrderFulfilment.SalesOrderLine
                    map (o,i) -> 
                        if (upper(o.ItemReference.PrimaryClassificationCode) == upper(p('global.lteNumberClass')))  
                            (o.SpecificationGroupXA filter (upper($.Name) == upper(p('global.numero')))).Value  
                            //o.Custom.AssetIntegrationID
                        else null
            ) filter !isEmpty($))[0]
var iccid = (flatten(payload.inputMessage.OrderFulfilment.SalesOrderLine.SpecificationGroupXA) filter upper($.Name) == p('global.iccid')).Value[0]
/*
var filterdItems = ((payload.inputMessage.OrderFulfilment.SalesOrderLine filter upper($.ServiceActionCode) == p('global.add')) 
						filter ((item, index) -> 
						    p('global.renoRepoIds') contains ("|" ++ upper(item.ItemReference.PrimaryClassificationCode) ++ "|")
						))						
*/
var packageId= p('global.renoRepo.packageId')
---
{
  "connectionNumber": connectionNumber,
  "simNumber": iccid,
  "packageId": packageId
  /*(flatten(inputBody.OrderFulfilment.SalesOrderLine.SpecificationGroupXA)
  					filter $.Name == p('global.serviceClassOcs')).Value[0]
  */
  //(flatten(filterdItems.SpecificationGroupXA) filter $.Name == p("global.offerClasseOcs"))[0].Value
}

%dw 2.0
output application/json
var inputBody = payload.inputMessage
var newMsisdn = (flatten(
                inputBody.OrderFulfilment.SalesOrderLine
                    map (o,i) -> 
                        if (upper(o.ItemReference.PrimaryClassificationCode) == upper(p('global.lteNumberClass')))  
                            (o.SpecificationGroupXA filter (upper($.Name) == upper(p('global.numero')))).Value  
                        else null
            ) filter !isEmpty($))[0]
var oldMsisdn = (flatten(
                inputBody.OrderFulfilment.SalesOrderLine
                    map (o,i) -> 
                        if (upper(o.ItemReference.PrimaryClassificationCode) == upper(p('global.lteNumberClass')))  
                            (o.SpecificationGroupXA filter (upper($.Name) == upper(p('global.numeroAnterior')))).Value  
                        else null
            ) filter !isEmpty($))[0]
---
{
  "newMsisdn": if (!isEmpty(newMsisdn)) 
                        newMsisdn 
                  else null,
  "oldMsisdn": if (!isEmpty(oldMsisdn)) 
                        oldMsisdn 
                  else null,
  "integrationId": inputBody.OrderFulfilment.SalesOrderLine.Custom.AssetIntegrationID[0]
}

%dw 2.0
output application/json
var inputBody = payload.inputMessage
var msisdn = (flatten(
                inputBody.OrderFulfilment.SalesOrderLine
                    map (o,i) -> 
                        if (upper(o.ItemReference.PrimaryClassificationCode) == upper(p('global.lteNumberClass')))  
