                        else null
            ) filter !isEmpty($))[0]
var parentPkgInstanceId = (flatten(
                inputBody.OrderFulfilment.SalesOrderLine
                    map (o,i) -> 
                        if (upper(o.ItemReference.PrimaryClassificationCode) == upper(p('global.lteNumberClass')))  
                            (o.SpecificationGroupXA filter (upper($.Name) == upper(p('global.parentPkgInstanceId')))).Value  
                        else null
            ) filter !isEmpty($))[0]
---
{
