%dw 2.0
output application/xml
var orderProcess = if (payload.Status == p('global.output.error.failed')) 500 else 200
---
{
    Actualiza_Aprovisionamiento: {
        Header: {
            IdentificadorPeticion: vars.inputPayload.inputMessage.OrderFulfilment.Identification.ID,
            SistemaPeticion: if(isEmpty(vars.inputPayload.inputMessage.OrderFulfilment.Sender.ApplicationID default "")) "SalesForce" else vars.inputPayload.inputMessage.OrderFulfilment.Sender.ApplicationID,
            UsuarioMDM: p('global.createOrder.usuarioMDM'),
            PasswordMDM: p('global.createOrder.passwordMDM')
        },
        Informacion: {
            (Id_Orden_Sistema_Origen: vars.inputPayload.inputMessage.OrderFulfilment.Identification.ID) if (!isBlank(payload.inputMessage.OrderFulfilment.Identification.ID)),
            Estado: if (orderProcess == 200) "Completed" else "Error",
            Fecha_Estado: now() >> "America/Bogota" as String,
            Resultado: if (orderProcess == 200) "Procesamiento exitoso" else "Procesamiento fallido"
        }
    }
}

%dw 2.0
output application/json
---
{
  "ICCID": ((flatten(vars.inputPayload.inputMessage.OrderFulfilment.SalesOrderLine map ((o, i) -> (
    if((o.ItemReference.PrimaryClassificationCode contains p('global.invCompleteFilters.lteSimcardClass'))) 
      (o.SpecificationGroupXA filter ($.Name == p('global.invCompleteFilters.iccid'))).Value 
    else "")))
) filter ($ != ""))[0] default "",
  "OrderId": vars.inputPayload.inputMessage.OrderFulfilment.Identification.ID, 
  "ServiceId": (vars.inputPayload.inputMessage.OrderFulfilment.AltKey filter ((item, index) -> item.AltKeyName == p('global.invCompleteFilters.serviceId')))[0].AltKeyValue,
  "MSISDN": if(upper(vars.inputPayload.inputMessage.OrderFulfilment.Scheduling.SubOrderType) contains p('global.invCompleteFilters.cancelacion')) (((vars.inputPayload.inputMessage.OrderFulfilment.SalesOrderLine filter $.ItemReference.PrimaryClassificationCode == p('global.invCompleteFilters.lteNumberClass')))[0].SpecificationGroupXA filter $.Name == p('global.invCompleteFilters.numero'))[0].Value
  else if(upper(p('global.invCompleteFilters.subOrderType')) contains upper("|" ++ vars.inputPayload.inputMessage.OrderFulfilment.Scheduling.SubOrderType ++ "|")) (flatten(vars.inputPayload.inputMessage.OrderFulfilment.SalesOrderLine.SpecificationGroupXA) filter ($.Name == p('global.invCompleteFilters.numeroAnterior')))[0].Value
  else (flatten(vars.inputPayload.inputMessage.OrderFulfilment.SalesOrderLine.SpecificationGroupXA) filter $.Name == p('global.invCompleteFilters.numero'))[0].Value,
  "NewMSISDN": 
    if(upper(p('global.invCompleteFilters.subOrderType')) contains upper("|" ++ vars.inputPayload.inputMessage.OrderFulfilment.Scheduling.SubOrderType ++ "|")) ((flatten(vars.inputPayload.inputMessage.OrderFulfilment.SalesOrderLine.SpecificationGroupXA)) filter $.Name == p('global.invCompleteFilters.numero'))[0].Value
    else "",
  "Tramit": vars.homologation_resp.homologation
}

%dw 2.0
output application/json
var integrationId = (vars.activeService filter upper($.Estado) != p("global.inactivo"))[0].Integration_Id
---
{
  "integrationId": vars.nroConexion,
  "msisdn": vars.nroConexion,
  "svas": [
  	{
	  "action": payload.ServiceActionCode,
	  "packageId": (payload.SpecificationGroupXA filter $.Name == p("global.offerClasseOcs"))[0].Value
  	}
  ]
}

%dw 2.0 output application/xml
var msisdn = (flatten((vars.inputPayload.inputMessage.OrderFulfilment.SalesOrderLine filter $.ItemReference.PrimaryClassificationCode == "LTE Number Class").SpecificationGroupXA) filter $.Name == "Numero")[0].Value var valueCondition = (flatten((vars.inputPayload.inputMessage.OrderFulfilment.SalesOrderLine filter $.ItemReference.PrimaryClassificationCode == "LTE Equipment Class").SpecificationGroupXA) filter $.Name == "IMEI")[0].Value var imei = if(sizeOf(valueCondition default "") > 0) valueCondition else ((vars.inputPayload.inputMessage.OrderFulfilment.SalesOrderLine filter $.ItemReference.PrimaryClassificationCode == "LTE Customer Equipment Class")[0].SpecificationGroupXA filter $.Name == "IMEI")[0].Value
--- WSRegistroPositivo: { WSRequestHeader: { System: { correlationID: null, processingServer: null }, Property: { value: null, name: null } }, RegistroPositivo: { sUsuarioETB: "", sIMEI: imei, sMSISDN: msisdn, sNombrePropietario: vars.inputPayload.inputMessage.OrderFulfilment.CustomerPartyAccount.Name, sDireccionPropietario: vars.inputPayload.inputMessage.OrderFulfilment.CustomerPartyAccount.Address.LineOne, iTipoUsuarioPropietario: vars.inputPayload.inputMessage.OrderFulfilment.CustomerPartyAccount.TypeCode, sTipoDocPropietario: vars.inputPayload.inputMessage.OrderFulfilment.CustomerPartyAccount.Custom.DocumentType, sDocPropietario: vars.inputPayload.inputMessage.OrderFulfilment.CustomerPartyAccount.Custom.DocumentNumber, sTelContactoPropietario: vars.inputPayload.inputMessage.OrderFulfilment.CustomerPartyAccount.ContactPerson.CompleteNumber, sNombreContacto: vars.inputPayload.inputMessage.OrderFulfilment.CustomerPartyAccount.ContactPerson.FirstName, sDireccionContacto: "", iTipoUsuarioAutorizado: "", sTipoDoAutorizado: "", sDocAutorizado: "", sTelContactoAutorizado: vars.inputPayload.inputMessage.OrderFulfilment.CustomerPartyAccount.ContactPerson.CompleteNumber } }
